-- Role-aware permissions for company members.
drop policy if exists products_company_member_access on public.products;
drop policy if exists products_read_company on public.products;
create policy products_read_company on public.products for select to authenticated using(private.has_company_access(company_id));
drop policy if exists products_write_company on public.products;
create policy products_write_company on public.products for insert to authenticated with check(private.has_company_access(company_id,array['owner','admin','manager']));
drop policy if exists products_update_company on public.products;
create policy products_update_company on public.products for update to authenticated using(private.has_company_access(company_id,array['owner','admin','manager'])) with check(private.has_company_access(company_id,array['owner','admin','manager']));
drop policy if exists products_delete_company on public.products;
create policy products_delete_company on public.products for delete to authenticated using(private.has_company_access(company_id,array['owner','admin']));
