drop policy if exists payment_transactions_company_access on public.payment_transactions;
drop policy if exists payments_read_company on public.payment_transactions;
create policy payments_read_company on public.payment_transactions for select to authenticated using(private.has_company_access(company_id,array['owner','admin','manager']) or (transaction_type='customer_receipt' and private.has_company_access(company_id,array['sales'])));
drop policy if exists payments_write_company on public.payment_transactions;
create policy payments_write_company on public.payment_transactions for insert to authenticated with check((transaction_type='customer_receipt' and private.has_company_access(company_id,array['owner','admin','manager','sales'])) or (transaction_type='supplier_payment' and private.has_company_access(company_id,array['owner','admin','manager'])));
